const upsertProjectMember = `-- name: UpsertProjectMember :one
INSERT INTO project_members (organization_id, project_id, user_id, can_approve, approval_limit, added_by)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (project_id, user_id) DO UPDATE
   SET can_approve = EXCLUDED.can_approve, approval_limit = EXCLUDED.approval_limit
RETURNING organization_id, project_id, user_id, can_approve, approval_limit, added_by, created_at
`

type UpsertProjectMemberParams struct {
	OrgID         uuid.UUID `json:"org_id"`
	ProjectID     uuid.UUID `json:"project_id"`
	UserID        uuid.UUID `json:"user_id"`
	CanApprove    bool      `json:"can_approve"`
	ApprovalLimit *int64    `json:"approval_limit"`
	AddedBy       uuid.UUID `json:"added_by"`
}

func (q *Queries) UpsertProjectMember(ctx context.Context, arg UpsertProjectMemberParams) (ProjectMember, error) {
	row := q.db.QueryRow(ctx, upsertProjectMember,
		arg.OrgID,
		arg.ProjectID,
		arg.UserID,
		arg.CanApprove,
		arg.ApprovalLimit,
		arg.AddedBy,
	)
	var i ProjectMember
	err := row.Scan(
		&i.OrganizationID,
		&i.ProjectID,
		&i.UserID,
		&i.CanApprove,
		&i.ApprovalLimit,
		&i.AddedBy,
		&i.CreatedAt,
	)
	return i, err
}
